import{H as e,V as t,et as n,j as r}from"./chunks/framework.C_EfTa_6.js";var i=JSON.parse(`{"title":"sendfile 零拷贝","description":"","frontmatter":{"title":"sendfile 零拷贝","order":10},"headers":[],"relativePath":"kernel/linux/develop/zero-copy.md","filePath":"kernel/linux/develop/zero-copy.md"}`),a={name:`kernel/linux/develop/zero-copy.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="sendfile-零拷贝" tabindex="-1">sendfile 零拷贝 <a class="header-anchor" href="#sendfile-零拷贝" aria-label="Permalink to “sendfile 零拷贝”">​</a></h1><p>零拷贝（Zero-Copy）的目标是消除数据在传输路径上的冗余内存拷贝。传统的数据传输路径——从磁盘文件到网络 socket——每个字节要经历四次拷贝：磁盘 DMA → 内核页缓存 → 用户态缓冲区（read 系统调用）→ 内核 socket 缓冲区（write 系统调用）→ 网卡 DMA。其中两次&quot;内核 ↔ 用户态&quot;的拷贝是纯粹的开销——数据只是路过用户态，用户程序通常并不修改它。零拷贝技术的本质是让数据不经过用户态，直接从内核的一处流转到另一处。</p><h2 id="sendfile-文件到-socket-的直接通道" tabindex="-1">sendfile：文件到 socket 的直接通道 <a class="header-anchor" href="#sendfile-文件到-socket-的直接通道" aria-label="Permalink to “sendfile：文件到 socket 的直接通道”">​</a></h2><p><code>sendfile</code> 是零拷贝最经典的实现，专门优化&quot;读文件然后发给网络&quot;这个高频场景（静态文件服务器、CDN 边缘节点）。</p><div class="language-c"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 传统方式：read + write，四次拷贝</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">char</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;"> buf</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4096</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">];</span></span>
<span class="line"><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">while</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> ((n </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> read</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(fd, buf, </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">sizeof</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(buf))) </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">    write</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sockfd, buf, n);</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// sendfile：文件到 socket，内核内完成</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">sendfile</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(sockfd, fd, </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">offset</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, filesize);</span></span></code></pre></div><p><code>sendfile</code> 的签名是&quot;把 fd 的数据发送到 sockfd&quot;——数据从页缓存直接进入 socket 的发送路径，完全不经过用户态。它要求数据源必须是支持 mmap 的文件（页缓存中的页面），目标必须是 socket——方向固定，不能反过来&quot;网络收包写文件&quot;（那是 splice 的领域）。</p><p>实现上，sendfile 的历史版本经历了从&quot;内核内拷贝&quot;到&quot;真正零拷贝&quot;的演进。早期实现（2.4 内核）在内核内做了一次页缓存 → socket 缓冲区的拷贝——省掉了用户态往返但不省内核内拷贝。现代实现（2.6+）配合网卡支持的 scatter-gather DMA，把页缓存的页面直接作为网卡 DMA 的描述符——数据从磁盘 DMA 到内存后，连内核内的拷贝也省掉了，CPU 只参与&quot;组装 DMA 描述符&quot;和&quot;更新文件位置&quot;。真正的数据搬运全部由 DMA 引擎完成。</p><h2 id="splice-任意两端之间的零拷贝管道" tabindex="-1">splice：任意两端之间的零拷贝管道 <a class="header-anchor" href="#splice-任意两端之间的零拷贝管道" aria-label="Permalink to “splice：任意两端之间的零拷贝管道”">​</a></h2><p><code>sendfile</code> 的方向限制（文件 → socket）在 <code>splice</code> 中被解除。splice 在两个文件描述符之间移动数据，其中至少一端必须是管道：</p><div class="language-c"><button title="Copy Code" class="copy"></button><span class="lang">c</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 文件 → 管道</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">splice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(file_fd, </span><span style="--shiki-light:#c62739;--shiki-dark:#F97583;">&amp;</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">off</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">pipefd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, size, SPLICE_F_MOVE);</span></span>
<span class="line"><span style="--shiki-light:#62687b;--shiki-dark:#818e99;">// 管道 → socket</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">splice</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#c13617;--shiki-dark:#FFAB70;">pipefd</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">[</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">], </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, sockfd, </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">NULL</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, size, SPLICE_F_MOVE);</span></span></code></pre></div><p>splice 的机制核心是<strong>页面引用传递</strong>而非数据拷贝。管道在内核中的缓冲区是页面的引用（<code>struct pipe_buffer</code> 持有 page 指针和偏移）——splice 往管道&quot;写&quot;数据时，实际是把源文件的页缓存页面引用挂到管道上，没有任何数据搬移；splice 从管道&quot;读&quot;到 socket 时，把页面引用从管道移交到 socket 的发送队列。数据页面本身在整个过程中一动不动。</p><p>这解释了 splice 的两个约束。一是为什么至少一端必须是管道——页面引用传递需要管道作为&quot;页面的中转站&quot;（没有其他内核对象支持这种语义）。二是为什么源端可能要求 <code>SPLICE_F_MOVE</code> 标志——页面引用移交要求源页面在移交后不再被修改，如果源文件被并发写入，引用语义失效，内核会回退到拷贝模式。理解&quot;引用传递 vs 数据拷贝&quot;的差异，是理解零拷贝性能收益边界的关键——数据要经过修改（压缩、加密、过滤）时，引用传递不可用，必须退化为拷贝。</p><h2 id="mmap-另一种-零拷贝-思路" tabindex="-1">mmap：另一种&quot;零拷贝&quot;思路 <a class="header-anchor" href="#mmap-另一种-零拷贝-思路" aria-label="Permalink to “mmap：另一种&quot;零拷贝&quot;思路”">​</a></h2><p>mmap 把文件映射到进程地址空间——访问映射区域的内存直接操作页缓存页面，省掉了 read 的&quot;内核 → 用户态&quot;拷贝。但它不是真正的零拷贝：进程通过内存访问数据（CPU 参与每一字节的读写），而 sendfile 的路径中 CPU 只设置 DMA 描述符。</p><p>mmap 在两种场景有优势：一是进程需要随机访问文件内容（sendfile 只能顺序流式），二是进程需要长时间反复使用同一份数据（映射一次，后续访问都是内存操作）。代价是 mmap 的页错误处理开销（首次访问每个页面触发一次缺页中断）和映射管理复杂度（文件截断时的 SIGBUS）。对&quot;读文件 → 发网络&quot;的流式场景，sendfile 在性能和简洁性上都完胜 mmap。</p><h2 id="零拷贝的工程边界" tabindex="-1">零拷贝的工程边界 <a class="header-anchor" href="#零拷贝的工程边界" aria-label="Permalink to “零拷贝的工程边界”">​</a></h2><p>零拷贝技术的收益前提是&quot;数据不需要被处理&quot;。静态文件服务器（Nginx 的 <code>sendfile on</code>）是完美场景——数据从磁盘原样到网络。但一旦中间有逻辑——TLS 加密（数据必须经 CPU 变换）、压缩、HTTP 头部注入、内容过滤——数据就必须经过用户态或内核态的变换步骤，sendfile 不可用。Nginx 处理 HTTPS 时默认关闭 sendfile 正是这个原因：TLS 加密要求数据经过加密模块，零拷贝路径被打破。</p><p>工程上判断是否能用零拷贝的问题清单：数据源是文件吗？目标是 socket 吗？数据需要被修改或检查吗？需要统计传输进度或做限速吗（sendfile 无用户态介入，进度统计受限）？答案全是&quot;是&quot;才考虑 sendfile；中间有变换就用传统 read/write 或 mmap 方案。</p><p>零拷贝与 <a href="./io_uring">io_uring</a> 的关系值得一提：io_uring 优化的是&quot;系统调用次数&quot;，零拷贝优化的是&quot;数据拷贝次数&quot;——两者正交且可以叠加。io_uring 的 <code>send</code> 操作可以携带 <code>IOSQE_ASYNC</code> 等标志配合注册缓冲区实现部分零拷贝，但完整的内核内数据直通（如 io_uring 的 splice 支持）仍在演进中。</p>`,19)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};